// Sanitize the token and map friendly keys -> Salesforce Lead fields.
// Reuses the same dictionary as the intake workflow's Build SF Body node.
const body = $json.body || {};
let token = String(body.token || '').trim().replace(/[^A-Za-z0-9\-_]/g, '');

const MAP = {
  firstname:           { sf: 'FirstName' },
  lastname:            { sf: 'LastName' },
  company:             { sf: 'Company' },
  email:               { sf: 'Email' },
  phone:               { sf: 'Phone' },
  mobilephone:         { sf: 'MobilePhone' },
  amountrequested:     { sf: 'csbs__Amount_Requested__c',  type: 'number' },
  averagedailybalance: { sf: 'Average_Daily_Balance__c',   type: 'number' },
  annualrevenue:       { sf: 'AnnualRevenue',              type: 'number' },
  monthlyrevenue:      { sf: 'csbs__Monthly_Revenue__c' },
  timeinbusiness:      { sf: 'csbs__Time_in_Business__c' },
  useofproceeds:       { sf: 'csbs__Use_of_Proceeds__c' },
  hasexistingloans:    { sf: 'Do_you_have_open_business_loans__c', type: 'yesno' },
  ein:                 { sf: 'EIN__c' },
  entitytype:          { sf: 'csbs__Entity_Type__c' },
  ownershippercentage: { sf: 'csbs__Ownership_Percentage__c', type: 'number' },
  ssn:                 { sf: 'csbs__Social_Security_Number_Unencrypted__c' },
  dob:                 { sf: 'csbs__Birthdate__c' },
  industry:            { sf: 'Industry' },
  homestreet:          { sf: 'csbs__Home_Address_Street__c' },
  homecity:            { sf: 'csbs__Home_Address_City__c' },
  homestate:           { sf: 'csbs__Home_Address_State__c' },
  businessstreet:      { sf: 'Street' },
  businesscity:        { sf: 'City' },
  businessstate:       { sf: 'State' },
  businesszip:         { sf: 'PostalCode' }
};

const lead = {};
for (const key in MAP) {
  let v = body[key];
  if (v === undefined || v === null || v === '') continue;
  const m = MAP[key];
  if (m.type === 'number') {
    const num = Number(String(v).replace(/[^0-9.-]/g, ''));
    if (!isFinite(num)) continue;
    v = num;
  } else if (m.type === 'yesno') {
    const s = String(v).toLowerCase().replace(/[^a-z0-9]/g, '');
    if (['yes','y','true','1'].indexOf(s) !== -1) v = 'Yes';
    else if (['no','n','false','0'].indexOf(s) !== -1) v = 'No';
    else continue;
  }
  lead[m.sf] = v;
}

if (body.creditscore !== undefined && body.creditscore !== null && body.creditscore !== '') {
  const cs = String(body.creditscore).trim();
  if (/^[0-9]{2,3}$/.test(cs)) lead['csbs__CreditScore__c'] = Number(cs);
  else lead['Credit_Score_Application__c'] = cs.slice(0, 100);
}

// OPTIONAL application-complete marker — set the real field name here once
// confirmed, e.g.:  lead['Application_Status__c'] = 'Completed';

if (!token) return { _notoken: true, lead };

const findUrl = 'https://bigthink.my.salesforce.com/services/data/v60.0/query/?q='
  + encodeURIComponent(`SELECT Id FROM Lead WHERE Landing_Page_Token__c='${token}' LIMIT 1`);

return { _notoken: false, token, findUrl, lead };

// Resolve the Lead Id and prepare the PATCH url + body.
const recs = Array.isArray($json.records) ? $json.records : [];
const lead = $('Build Update').item.json.lead || {};
if (!recs.length || !recs[0].Id) {
  return { _notfound: true };
}
const id = recs[0].Id;
const patchUrl = 'https://bigthink.my.salesforce.com/services/data/v60.0/sobjects/Lead/' + id;
return { _notfound: false, patchUrl, lead };
